using Matrix6d = Eigen::Matrix<Real, 6, 6>;

// Helper: compute 2x2 rotation matrix for angle theta
Matrix2d rotationMatrix(Real theta) {
    return (Matrix2d() << std::cos(theta), -std::sin(theta),
                           std::sin(theta),  std::cos(theta)).finished();
}

